-- 13_views_live_apply.sql  -  GANTI view asli dengan versi dari HR (isi sama dengan 09_views_test.sql, nama tanpa _test)
--   struktur_lengkap_oke, divisions, atasan_terkait
-- BACKUP otomatis: definisi yang sedang berlaku disalin dulu ke struktur_lengkap_oke_backup, divisions_backup, atasan_terkait_backup
--   (hanya dibuat bila belum ada, jadi aman dijalankan ulang tanpa menimpa backup yang pertama). Tidak menyentuh data tabel.
-- Rollback: 14_views_live_rollback.sql (mengembalikan dari *_backup; view backup dibiarkan)
-- Dampak: karyawan nonaktif tidak lagi muncul; jabatan, divisi, atasan, PIC/PS (pengganti nota_dinas) mengikuti HR.
--         nota_dinas apam tidak lagi dibaca view ini. View turunan (task_latest_status, *_oke, dll) otomatis ikut.
-- Tarif SPPD (base_name, rate_sppd, nomor_sppd) dan id_base TIDAK ikut PS/PIC: selalu menurut jabatan asli karyawan.
--         Hanya real_base (PUK divisi, atasan_terkait) yang ikut PS/PIC.
SET NAMES utf8mb4;

-- 1) BACKUP definisi yang sedang berlaku
SET @def_struktur_lengkap_oke = (SELECT `view_definition` FROM `information_schema`.`views` WHERE `table_schema` = 'ptpemaco_apam' AND `table_name` = 'struktur_lengkap_oke');
SET @sql = IF((SELECT COUNT(*) FROM `information_schema`.`views` WHERE `table_schema` = 'ptpemaco_apam' AND `table_name` = 'struktur_lengkap_oke_backup') = 0 AND @def_struktur_lengkap_oke IS NOT NULL,
  CONCAT('CREATE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`struktur_lengkap_oke_backup` AS ', @def_struktur_lengkap_oke), 'DO 0');
PREPARE st FROM @sql; EXECUTE st; DEALLOCATE PREPARE st;
SET @def_divisions = (SELECT `view_definition` FROM `information_schema`.`views` WHERE `table_schema` = 'ptpemaco_apam' AND `table_name` = 'divisions');
SET @sql = IF((SELECT COUNT(*) FROM `information_schema`.`views` WHERE `table_schema` = 'ptpemaco_apam' AND `table_name` = 'divisions_backup') = 0 AND @def_divisions IS NOT NULL,
  CONCAT('CREATE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`divisions_backup` AS ', REPLACE(@def_divisions,'`struktur_lengkap_oke`','`struktur_lengkap_oke_backup`')), 'DO 0');
PREPARE st FROM @sql; EXECUTE st; DEALLOCATE PREPARE st;
SET @def_atasan_terkait = (SELECT `view_definition` FROM `information_schema`.`views` WHERE `table_schema` = 'ptpemaco_apam' AND `table_name` = 'atasan_terkait');
SET @sql = IF((SELECT COUNT(*) FROM `information_schema`.`views` WHERE `table_schema` = 'ptpemaco_apam' AND `table_name` = 'atasan_terkait_backup') = 0 AND @def_atasan_terkait IS NOT NULL,
  CONCAT('CREATE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`atasan_terkait_backup` AS ', REPLACE(@def_atasan_terkait,'`struktur_lengkap_oke`','`struktur_lengkap_oke_backup`')), 'DO 0');
PREPARE st FROM @sql; EXECUTE st; DEALLOCATE PREPARE st;

-- 2) GANTI dengan versi HR
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`struktur_lengkap_oke` AS
select coalesce(`h1`.`employe_id`,`h2`.`employe_id`,`h3`.`employe_id`,`h4`.`employe_id`,`h5`.`employe_id`) AS `direct_atasan`,
  `h1`.`employe_id` AS `level_1`,`h2`.`employe_id` AS `level_2`,`h3`.`employe_id` AS `level_3`,`h4`.`employe_id` AS `level_4`,`h5`.`employe_id` AS `level_5`,
  `u`.`employe_id` AS `employe_id`,
  `b`.`id` AS `user_id`,
  `p1`.`id` AS `position_id`,
  concat(`p1`.`position_name`,coalesce(concat(' / ',if(`pk`.`role_assignment` = 'as_pic','PIC','PS'),' ',`pk`.`position_name`),'')) AS `position_name`,
  coalesce((case when `pk`.`position_name` like 'Komisaris Utama%' then 1 when trim(`pk`.`position_name`) = 'Direktur Utama' then 3 when `pk`.`position_name` like 'Manajer Eksekutif%' then 6 when `pk`.`position_level` = 'Komisaris' then 2 when `pk`.`position_level` = 'Direktur' then 4 when `pk`.`position_level` = 'Manajer' then 7 when `pk`.`position_level` = 'Supervisor' then 8 when `pk`.`position_level` = 'Staf' then 9 when `pk`.`position_level` = 'Tenaga Pendukung' then 10 end),(case when `p1`.`position_name` like 'Komisaris Utama%' then 1 when trim(`p1`.`position_name`) = 'Direktur Utama' then 3 when `p1`.`position_name` like 'Manajer Eksekutif%' then 6 when `p1`.`position_level` = 'Komisaris' then 2 when `p1`.`position_level` = 'Direktur' then 4 when `p1`.`position_level` = 'Manajer' then 7 when `p1`.`position_level` = 'Supervisor' then 8 when `p1`.`position_level` = 'Staf' then 9 when `p1`.`position_level` = 'Tenaga Pendukung' then 10 end)) AS `real_base`,
  (case when `p1`.`position_name` like 'Komisaris Utama%' then 1 when trim(`p1`.`position_name`) = 'Direktur Utama' then 3 when `p1`.`position_name` like 'Manajer Eksekutif%' then 6 when `p1`.`position_level` = 'Komisaris' then 2 when `p1`.`position_level` = 'Direktur' then 4 when `p1`.`position_level` = 'Manajer' then 7 when `p1`.`position_level` = 'Supervisor' then 8 when `p1`.`position_level` = 'Staf' then 9 when `p1`.`position_level` = 'Tenaga Pendukung' then 10 end) AS `id_base`,
  `z`.`base_name` AS `base_name`,`z`.`rate_sppd` AS `rate_sppd`,`z`.`nomor_sppd` AS `nomor_sppd`,
  `p1`.`division_id` AS `organization_id`,
  `dv`.`division_name` AS `organization_name`,
  `dv`.`board_id` AS `board_id`,
  `hb`.`board_name` AS `board_name`,
  `ep`.`pic` AS `as_pic`,
  left(if(nullif(trim(`u`.`last_name`),'') is null or locate(lower(trim(`u`.`last_name`)),lower(trim(`u`.`first_name`))) > 0,
          trim(`u`.`first_name`),concat(trim(`u`.`first_name`),' ',trim(`u`.`last_name`))),100) AS `first_name`,
  `epd`.`gender` AS `gender`,`epd`.`religion` AS `religion`,`epd`.`birthday` AS `birthday`,`epd`.`birthday_place` AS `birthday_place`,`epd`.`marital_status` AS `marital_status`,
  `epd`.`photo` AS `img`,
  `u`.`active` AS `employe_active`,
  coalesce(`b`.`email`,`u`.`email`) AS `email`,
  `b`.`roles` AS `roles`,
  concat('https://hr-api.ptpema.co.id/storage/photo/employee-photo/',`epd`.`photo`) AS `photo`,
  (case when regexp_like(`epd`.`phone_number`,'^08[0-9]{8,12}$') then concat('628',substr(`epd`.`phone_number`,3))
      when regexp_like(`epd`.`phone_number`,'^628[0-9]{7,12}$') then `epd`.`phone_number`
      when regexp_like(`epd`.`phone_number`,'^\\+[1-9][0-9]{6,14}$') then `epd`.`phone_number`
      when regexp_like(`epd`.`phone_number`,'^[1-9][0-9]{7,14}$') then `epd`.`phone_number` else NULL end) AS `phone_number`
from `ptpemaco_hr_production`.`users` `u`
join (select `employe_id`,min(`position_id`) AS `pid`,max(`is_pic`) AS `pic` from `ptpemaco_hr_production`.`employee_positions` group by `employe_id`) `ep` on `ep`.`employe_id` = `u`.`employe_id`
join `ptpemaco_hr_production`.`positions` `p1` on `p1`.`id` = `ep`.`pid`
join `ptpemaco_hr_production`.`divisions` `dv` on `dv`.`id` = `p1`.`division_id`
join `ptpemaco_hr_production`.`board_organizations` `hb` on `hb`.`id` = `dv`.`board_id`
left join (select `x`.* from `ptpemaco_hr_production`.`employee_personal_data` `x` where `x`.`id` = (select max(`y`.`id`) from `ptpemaco_hr_production`.`employee_personal_data` `y` where `y`.`employe_id` = `x`.`employe_id`)) `epd` on `epd`.`employe_id` = `u`.`employe_id`
left join `ptpemaco_apam`.`users` `b` on `b`.`id` = (select max(`x`.`id`) from `ptpemaco_apam`.`users` `x` where lower(`x`.`email`) = lower(`u`.`email`))
left join (select `pc`.`employe_id` AS `employe_id`,`pc`.`role_assignment` AS `role_assignment`,`pp`.`position_name` AS `position_name`,`pp`.`position_level` AS `position_level` from `ptpemaco_hr_production`.`pic` `pc` join `ptpemaco_hr_production`.`positions` `pp` on `pp`.`id` = `pc`.`position_id` where curdate() between `pc`.`start_date` and `pc`.`end_date` and `pc`.`id` = (select `q`.`id` from `ptpemaco_hr_production`.`pic` `q` where `q`.`employe_id` = `pc`.`employe_id` and curdate() between `q`.`start_date` and `q`.`end_date` order by (`q`.`role_assignment` = 'as_pic') desc,`q`.`id` desc limit 1)) `pk` on `pk`.`employe_id` = `u`.`employe_id`
left join `ptpemaco_apam`.`base_positions` `z` on `z`.`id` = (case when `p1`.`position_name` like 'Komisaris Utama%' then 1 when trim(`p1`.`position_name`) = 'Direktur Utama' then 3 when `p1`.`position_name` like 'Manajer Eksekutif%' then 6 when `p1`.`position_level` = 'Komisaris' then 2 when `p1`.`position_level` = 'Direktur' then 4 when `p1`.`position_level` = 'Manajer' then 7 when `p1`.`position_level` = 'Supervisor' then 8 when `p1`.`position_level` = 'Staf' then 9 when `p1`.`position_level` = 'Tenaga Pendukung' then 10 end)
left join (select `x`.`employe_id` AS `employe_id`,`x`.`pid` AS `pid` from (select `u`.`employe_id` AS `employe_id`,`ep`.`pid` AS `pid` from `ptpemaco_hr_production`.`users` `u` join (select `employe_id`,min(`position_id`) AS `pid` from `ptpemaco_hr_production`.`employee_positions` group by `employe_id`) `ep` on `ep`.`employe_id` = `u`.`employe_id` where `u`.`active` = 1 and not exists (select 1 from `ptpemaco_hr_production`.`pic` `px` join `ptpemaco_hr_production`.`users` `ux` on `ux`.`employe_id` = `px`.`employe_id` and `ux`.`active` = 1 where `px`.`position_id` = `ep`.`pid` and curdate() between `px`.`start_date` and `px`.`end_date`) union all select `pc`.`employe_id`,`pc`.`position_id` from `ptpemaco_hr_production`.`pic` `pc` join `ptpemaco_hr_production`.`users` `uc` on `uc`.`employe_id` = `pc`.`employe_id` and `uc`.`active` = 1 where curdate() between `pc`.`start_date` and `pc`.`end_date` and `pc`.`id` = (select `q`.`id` from `ptpemaco_hr_production`.`pic` `q` join `ptpemaco_hr_production`.`users` `uq` on `uq`.`employe_id` = `q`.`employe_id` and `uq`.`active` = 1 where `q`.`position_id` = `pc`.`position_id` and curdate() between `q`.`start_date` and `q`.`end_date` order by (`q`.`role_assignment` = 'as_pic') desc,`q`.`id` desc limit 1)) `x`) `h1` on `h1`.`pid` = `p1`.`parent_id`
left join `ptpemaco_hr_production`.`positions` `p2` on `p2`.`id` = `p1`.`parent_id`
left join (select `x`.`employe_id` AS `employe_id`,`x`.`pid` AS `pid` from (select `u`.`employe_id` AS `employe_id`,`ep`.`pid` AS `pid` from `ptpemaco_hr_production`.`users` `u` join (select `employe_id`,min(`position_id`) AS `pid` from `ptpemaco_hr_production`.`employee_positions` group by `employe_id`) `ep` on `ep`.`employe_id` = `u`.`employe_id` where `u`.`active` = 1 and not exists (select 1 from `ptpemaco_hr_production`.`pic` `px` join `ptpemaco_hr_production`.`users` `ux` on `ux`.`employe_id` = `px`.`employe_id` and `ux`.`active` = 1 where `px`.`position_id` = `ep`.`pid` and curdate() between `px`.`start_date` and `px`.`end_date`) union all select `pc`.`employe_id`,`pc`.`position_id` from `ptpemaco_hr_production`.`pic` `pc` join `ptpemaco_hr_production`.`users` `uc` on `uc`.`employe_id` = `pc`.`employe_id` and `uc`.`active` = 1 where curdate() between `pc`.`start_date` and `pc`.`end_date` and `pc`.`id` = (select `q`.`id` from `ptpemaco_hr_production`.`pic` `q` join `ptpemaco_hr_production`.`users` `uq` on `uq`.`employe_id` = `q`.`employe_id` and `uq`.`active` = 1 where `q`.`position_id` = `pc`.`position_id` and curdate() between `q`.`start_date` and `q`.`end_date` order by (`q`.`role_assignment` = 'as_pic') desc,`q`.`id` desc limit 1)) `x`) `h2` on `h2`.`pid` = `p2`.`parent_id`
left join `ptpemaco_hr_production`.`positions` `p3` on `p3`.`id` = `p2`.`parent_id`
left join (select `x`.`employe_id` AS `employe_id`,`x`.`pid` AS `pid` from (select `u`.`employe_id` AS `employe_id`,`ep`.`pid` AS `pid` from `ptpemaco_hr_production`.`users` `u` join (select `employe_id`,min(`position_id`) AS `pid` from `ptpemaco_hr_production`.`employee_positions` group by `employe_id`) `ep` on `ep`.`employe_id` = `u`.`employe_id` where `u`.`active` = 1 and not exists (select 1 from `ptpemaco_hr_production`.`pic` `px` join `ptpemaco_hr_production`.`users` `ux` on `ux`.`employe_id` = `px`.`employe_id` and `ux`.`active` = 1 where `px`.`position_id` = `ep`.`pid` and curdate() between `px`.`start_date` and `px`.`end_date`) union all select `pc`.`employe_id`,`pc`.`position_id` from `ptpemaco_hr_production`.`pic` `pc` join `ptpemaco_hr_production`.`users` `uc` on `uc`.`employe_id` = `pc`.`employe_id` and `uc`.`active` = 1 where curdate() between `pc`.`start_date` and `pc`.`end_date` and `pc`.`id` = (select `q`.`id` from `ptpemaco_hr_production`.`pic` `q` join `ptpemaco_hr_production`.`users` `uq` on `uq`.`employe_id` = `q`.`employe_id` and `uq`.`active` = 1 where `q`.`position_id` = `pc`.`position_id` and curdate() between `q`.`start_date` and `q`.`end_date` order by (`q`.`role_assignment` = 'as_pic') desc,`q`.`id` desc limit 1)) `x`) `h3` on `h3`.`pid` = `p3`.`parent_id`
left join `ptpemaco_hr_production`.`positions` `p4` on `p4`.`id` = `p3`.`parent_id`
left join (select `x`.`employe_id` AS `employe_id`,`x`.`pid` AS `pid` from (select `u`.`employe_id` AS `employe_id`,`ep`.`pid` AS `pid` from `ptpemaco_hr_production`.`users` `u` join (select `employe_id`,min(`position_id`) AS `pid` from `ptpemaco_hr_production`.`employee_positions` group by `employe_id`) `ep` on `ep`.`employe_id` = `u`.`employe_id` where `u`.`active` = 1 and not exists (select 1 from `ptpemaco_hr_production`.`pic` `px` join `ptpemaco_hr_production`.`users` `ux` on `ux`.`employe_id` = `px`.`employe_id` and `ux`.`active` = 1 where `px`.`position_id` = `ep`.`pid` and curdate() between `px`.`start_date` and `px`.`end_date`) union all select `pc`.`employe_id`,`pc`.`position_id` from `ptpemaco_hr_production`.`pic` `pc` join `ptpemaco_hr_production`.`users` `uc` on `uc`.`employe_id` = `pc`.`employe_id` and `uc`.`active` = 1 where curdate() between `pc`.`start_date` and `pc`.`end_date` and `pc`.`id` = (select `q`.`id` from `ptpemaco_hr_production`.`pic` `q` join `ptpemaco_hr_production`.`users` `uq` on `uq`.`employe_id` = `q`.`employe_id` and `uq`.`active` = 1 where `q`.`position_id` = `pc`.`position_id` and curdate() between `q`.`start_date` and `q`.`end_date` order by (`q`.`role_assignment` = 'as_pic') desc,`q`.`id` desc limit 1)) `x`) `h4` on `h4`.`pid` = `p4`.`parent_id`
left join `ptpemaco_hr_production`.`positions` `p5` on `p5`.`id` = `p4`.`parent_id`
left join (select `x`.`employe_id` AS `employe_id`,`x`.`pid` AS `pid` from (select `u`.`employe_id` AS `employe_id`,`ep`.`pid` AS `pid` from `ptpemaco_hr_production`.`users` `u` join (select `employe_id`,min(`position_id`) AS `pid` from `ptpemaco_hr_production`.`employee_positions` group by `employe_id`) `ep` on `ep`.`employe_id` = `u`.`employe_id` where `u`.`active` = 1 and not exists (select 1 from `ptpemaco_hr_production`.`pic` `px` join `ptpemaco_hr_production`.`users` `ux` on `ux`.`employe_id` = `px`.`employe_id` and `ux`.`active` = 1 where `px`.`position_id` = `ep`.`pid` and curdate() between `px`.`start_date` and `px`.`end_date`) union all select `pc`.`employe_id`,`pc`.`position_id` from `ptpemaco_hr_production`.`pic` `pc` join `ptpemaco_hr_production`.`users` `uc` on `uc`.`employe_id` = `pc`.`employe_id` and `uc`.`active` = 1 where curdate() between `pc`.`start_date` and `pc`.`end_date` and `pc`.`id` = (select `q`.`id` from `ptpemaco_hr_production`.`pic` `q` join `ptpemaco_hr_production`.`users` `uq` on `uq`.`employe_id` = `q`.`employe_id` and `uq`.`active` = 1 where `q`.`position_id` = `pc`.`position_id` and curdate() between `q`.`start_date` and `q`.`end_date` order by (`q`.`role_assignment` = 'as_pic') desc,`q`.`id` desc limit 1)) `x`) `h5` on `h5`.`pid` = `p5`.`parent_id`
where `u`.`active` = 1;

CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`divisions` AS
select `d`.`id` AS `organization_id`,`d`.`board_id` AS `board_id`,`d`.`division_name` AS `organization_name`,
(select coalesce(
    coalesce(
        (select `p`.`employe_id` from `ptpemaco_hr_production`.`pic` `p`
           join `ptpemaco_hr_production`.`positions` `ps` on `ps`.`id` = `p`.`position_id`
           join `ptpemaco_hr_production`.`users` `u` on `u`.`employe_id` = `p`.`employe_id` and `u`.`active` = 1
          where `ps`.`division_id` = `d`.`id` and `ps`.`position_level` = 'Manajer'
            and curdate() between `p`.`start_date` and `p`.`end_date`
          order by (`p`.`role_assignment` = 'as_pic') desc, `p`.`id` desc limit 1),
        (select `s`.`employe_id` from `ptpemaco_apam`.`struktur_lengkap_oke` `s`
          where `s`.`organization_id` = `d`.`id` and `s`.`real_base` = 7 limit 1)),
    coalesce(
        (select `p`.`employe_id` from `ptpemaco_hr_production`.`pic` `p`
           join `ptpemaco_hr_production`.`positions` `ps` on `ps`.`id` = `p`.`position_id`
           join `ptpemaco_hr_production`.`users` `u` on `u`.`employe_id` = `p`.`employe_id` and `u`.`active` = 1
          where `ps`.`division_id` = `d`.`id` and `ps`.`position_level` = 'Supervisor'
            and curdate() between `p`.`start_date` and `p`.`end_date`
          order by (`p`.`role_assignment` = 'as_pic') desc, `p`.`id` desc limit 1),
        (select `s`.`employe_id` from `ptpemaco_apam`.`struktur_lengkap_oke` `s`
          where `s`.`organization_id` = `d`.`id` and `s`.`real_base` = 8 limit 1)),
    coalesce(
        (select `p`.`employe_id` from `ptpemaco_hr_production`.`pic` `p`
           join `ptpemaco_hr_production`.`positions` `ps` on `ps`.`id` = `p`.`position_id`
           join `ptpemaco_hr_production`.`users` `u` on `u`.`employe_id` = `p`.`employe_id` and `u`.`active` = 1
          where `ps`.`division_id` = `d`.`id` and `ps`.`position_level` = 'Staf'
            and curdate() between `p`.`start_date` and `p`.`end_date`
          order by (`p`.`role_assignment` = 'as_pic') desc, `p`.`id` desc limit 1),
        (select `s`.`employe_id` from `ptpemaco_apam`.`struktur_lengkap_oke` `s`
          where `s`.`organization_id` = `d`.`id` and `s`.`real_base` = 9 limit 1))
  )) AS `PUK`,
coalesce(
   (select `s`.`employe_id` from `ptpemaco_apam`.`struktur_lengkap_oke` `s` where `s`.`board_id` = `d`.`board_id` and `s`.`id_base` = 4 limit 1),
   (select `s`.`employe_id` from `ptpemaco_apam`.`struktur_lengkap_oke` `s` where `s`.`id_base` = 3 limit 1)) AS `dir`,
(select count(`ps`.`project_id`) from `ptpemaco_apam`.`project_stages` `ps` where `ps`.`division` = `d`.`id` and year(`ps`.`end_date`) = year(curdate())) AS `jumlah`
from `ptpemaco_hr_production`.`divisions` `d`
join `ptpemaco_apam`.`organizations` `o` on `o`.`organization_id` = `d`.`id` and `o`.`is_division` = 1;

CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`atasan_terkait` AS
